import os,json,urllib.request,urllib.error,sys
from pathlib import Path
root=Path('/workspace/mcp-eval')
def call(method,path,body=None,name=None):
 req=urllib.request.Request(os.environ['MCPJAM_API_URL'].rstrip('/')+path,data=json.dumps(body).encode() if body is not None else None,headers={'Authorization':'Bearer '+os.environ['MCPJAM_API_KEY'],'Content-Type':'application/json'},method=method)
 try:
  with urllib.request.urlopen(req,timeout=20) as r: status,data=r.status,r.read().decode()
 except urllib.error.HTTPError as e: status,data=e.code,e.read().decode()
 try: data=json.loads(data)
 except: pass
 result={'http_status':status,'body':data}
 if name: (root/(name+'.json')).write_text(json.dumps(result,indent=2))
 print(json.dumps(result,indent=2));return result
if __name__=='__main__': call(sys.argv[1],sys.argv[2],json.load(open(sys.argv[3])) if len(sys.argv)>3 and sys.argv[3]!='-' else None,sys.argv[4] if len(sys.argv)>4 else None)
